```typescript
// File: /Users/sacino/musclehacking/src/scripts/social-share.ts, Lines 11-20

rail.querySelector<HTMLAnchorElement>('[data-copy-page-link]')?.addEventListener('click', async (event) => {
  event.preventDefault();
  const link = event.currentTarget as HTMLAnchorElement;
  try {
    await navigator.clipboard.writeText(link.href);
    link.dataset.copied = 'true';
  } catch {
    link.dataset.copied = 'false';
  }
});
```
